public class ScpEqualityVerifier {
    public static void verifyEquality(String lit1, String lit2, String heapObj) {
        // Reference checks (memory address comparison)
        boolean sameLiteralRef = (lit1 == lit2);
        boolean sameHeapRef = (lit1 == heapObj);

        // Content checks (character-by-character value comparison)
        boolean sameContent = lit1.equals(heapObj);

        System.out.println("Literal vs Literal (==)   : " + sameLiteralRef + " [Shared SCP Memory]");
        System.out.println("Literal vs Heap Obj (==)  : " + sameHeapRef + " [Distinct Heap Object]");
        System.out.println("Literal vs Heap (.equals) : " + sameContent + " [Equivalent Character Value]");
    }
}

public class InterningEngine {
    public static void optimizeMemory(String scpBase, String rawInput) {
        // Dynamic string created at runtime residing in normal Heap memory
        String heapCopy = new String(rawInput);

        System.out.println("Before intern: " + (scpBase == heapCopy)); // false

        // Fetch or register canonical reference inside the SCP
        String canonicalRef = heapCopy.intern();

        System.out.println("After intern  : " + (scpBase == canonicalRef)); // true
        System.out.println("Memory Optimization: Canonical reference retrieved from SCP.");
    }
}

public class ImmutabilityProof {
    public static void testImmutability(String original) {
        int originalHash = System.identityHashCode(original);
        System.out.println("Original before operations: " + original + " [Address: " + originalHash + "]");

        // Attempt in-place mutations (return values intentionally ignored)
        original.concat(" Developer");
        original.toUpperCase();
        original.replace('a', 'o');

        int afterHash = System.identityHashCode(original);
        System.out.println("Original after operations : " + original + " [Address: " + afterHash + "]");
        System.out.println("Immutability Confirmed    : " + (originalHash == afterHash && original.equals("Java")));
    }
}

public class SecurityTokenValidator {
    public static boolean validateAccess(String userRole) {
        System.out.println("Entering security checkpoint with role: " + userRole);

        // Simulate third-party untrusted library invocation
        untrustedPlugin(userRole);

        // Because String is immutable, userRole cannot be mutated by untrustedPlugin
        if (userRole.equals("ROLE_ADMIN")) {
            System.out.println("ACCESS GRANTED: Administrator privileges.");
            return true;
        } else {
            System.out.println("ACCESS RESTRICTED: Role remained '" + userRole + "' safely.");
            return false;
        }
    }

    private static void untrustedPlugin(String token) {
        // Plugin cannot modify caller's String object in Heap
        token = "ROLE_ADMIN"; // Rebinds local stack variable only
    }
}

public class TwoPointerPalindrome {
    public static boolean isPalindrome(String input) {
        if (input == null) return false;

        int left = 0;
        int right = input.length() - 1;

        while (left < right) {
            char chLeft = input.charAt(left);
            char chRight = input.charAt(right);

            // Skip non-alphanumeric characters
            if (!Character.isLetterOrDigit(chLeft)) {
                left++;
            } else if (!Character.isLetterOrDigit(chRight)) {
                right--;
            } else {
                if (Character.toLowerCase(chLeft) != Character.toLowerCase(chRight)) {
                    return false;
                }
                left++;
                right--;
            }
        }
        return true;
    }
}

public class EmailSanitizer {
    public static void sanitizeAndParse(String rawEmail) {
        if (rawEmail == null || rawEmail.isBlank()) {
            System.out.println("Invalid email input.");
            return;
        }

        // Clean surrounding whitespace and normalize case
        String cleanEmail = rawEmail.strip().toLowerCase();
        int atIndex = cleanEmail.indexOf('@');

        if (atIndex <= 0 || atIndex == cleanEmail.length() - 1) {
            System.out.println("Malformed email address.");
            return;
        }

        String username = cleanEmail.substring(0, atIndex);
        String domain = cleanEmail.substring(atIndex + 1);

        System.out.println("Clean Email : " + cleanEmail);
        System.out.println("Username    : " + username);
        System.out.println("Domain      : " + domain);
        System.out.println("Is College  : " + domain.endsWith(".edu"));
    }
}

public class PiiDataMasker {
    public static String maskIdentifier(String rawNumber) {
        if (rawNumber == null || rawNumber.length() < 4) {
            return "INVALID_ID";
        }

        int maskLength = rawNumber.length() - 4;
        String visibleDigits = rawNumber.substring(maskLength);

        // Modern Java repeat() method for concise immutable string generation
        String maskedPrefix = "*".repeat(maskLength);

        return maskedPrefix + visibleDigits;
    }
}

public class CharacterCategoryAnalyzer {
    public static void analyzeText(String text) {
        if (text == null) return;

        int vowels = 0, consonants = 0, digits = 0, spaces = 0, symbols = 0;
        String vowelList = "AEIOUaeiou";

        for (char ch : text.toCharArray()) {
            if (Character.isDigit(ch)) {
                digits++;
            } else if (Character.isWhitespace(ch)) {
                spaces++;
            } else if (Character.isLetter(ch)) {
                if (vowelList.indexOf(ch) != -1) {
                    vowels++;
                } else {
                    consonants++;
                }
            } else {
                symbols++;
            }
        }

        System.out.println("Vowels: " + vowels + " | Consonants: " + consonants);
        System.out.println("Digits: " + digits + " | Spaces: " + spaces + " | Symbols: " + symbols);
    }
}

public class TitleCaseCapitalizer {
    public static String toTitleCase(String title) {
        if (title == null || title.isBlank()) return "";

        String[] words = title.trim().split("\\s+");

        for (int i = 0; i < words.length; i++) {
            String word = words[i].toLowerCase();
            if (word.length() > 0) {
                char firstChar = Character.toUpperCase(word.charAt(0));
                words[i] = firstChar + word.substring(1);
            }
        }

        return String.join(" ", words);
    }
}

public class SubstringOccurrenceCounter {
    public static int countOccurrences(String text, String target, boolean allowOverlap) {
        if (text == null || target == null || target.isEmpty()) return 0;

        int count = 0;
        int index = text.indexOf(target);

        while (index != -1) {
            count++;
            // If overlap allowed, advance by 1; otherwise advance by target length
            int step = allowOverlap ? 1 : target.length();
            index = text.indexOf(target, index + step);
        }

        return count;
    }
}

public class CustomUrlParser {
    public static void parseUrl(String url) {
        if (url == null || !url.contains("://")) {
            System.out.println("Invalid URL format.");
            return;
        }

        int schemeEnd = url.indexOf("://");
        String protocol = url.substring(0, schemeEnd);

        String remainder = url.substring(schemeEnd + 3);
        int pathStart = remainder.indexOf('/');

        String hostAndPort = (pathStart != -1) ? remainder.substring(0, pathStart) : remainder;
        String path = (pathStart != -1) ? remainder.substring(pathStart) : "/";

        String host = hostAndPort;
        int defaultPort = protocol.equalsIgnoreCase("https") ? 443 : 80;
        int port = defaultPort;

        if (hostAndPort.contains(":")) {
            String[] parts = hostAndPort.split(":");
            host = parts[0];
            port = Integer.parseInt(parts[1]);
        }

        System.out.println("Protocol: " + protocol + " | Host: " + host + " | Port: " + port + " | Path: " + path);
    }
}

import java.util.ArrayList;
import java.util.List;

public class CsvRecordParser {
    public static List<String> parseCsvLine(String line) {
        List<String> fields = new ArrayList<>();
        if (line == null) return fields;

        StringBuilder currentField = new StringBuilder();
        boolean inQuotes = false;

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);

            if (c == '"') {
                inQuotes = !inQuotes; // Toggle quoting mode
            } else if (c == ',' && !inQuotes) {
                fields.add(currentField.toString().trim());
                currentField.setLength(0); // Reset for next token
            } else {
                currentField.append(c);
            }
        }
        fields.add(currentField.toString().trim());

        return fields;
    }
}

public class LexicographicalSorter {
    public static void sortStrings(String[] arr) {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                // compareTo returns < 0 if arr[j] < arr[j+1], > 0 if arr[j] > arr[j+1]
                if (arr[j].compareToIgnoreCase(arr[j + 1]) > 0) {
                    String temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }
}

public class CustomStringReplacer {
    public static String replaceWord(String source, String target, String replacement) {
        if (source == null || target == null || target.isEmpty()) return source;

        StringBuilder result = new StringBuilder();
        int startIndex = 0;
        int foundIndex;

        while ((foundIndex = source.indexOf(target, startIndex)) != -1) {
            // Append segment preceding the match
            result.append(source.substring(startIndex, foundIndex));
            result.append(replacement);
            // Jump past the matched target
            startIndex = foundIndex + target.length();
        }

        // Append remaining tail
        result.append(source.substring(startIndex));
        return result.toString();
    }
}

public class AnagramEvaluator {
    public static boolean areAnagrams(String s1, String s2) {
        if (s1 == null || s2 == null) return false;

        // Strip non-letter characters and normalize to lowercase
        String clean1 = s1.replaceAll("\\s+", "").toLowerCase();
        String clean2 = s2.replaceAll("\\s+", "").toLowerCase();

        if (clean1.length() != clean2.length()) return false;

        int[] frequency = new int[26];

        for (int i = 0; i < clean1.length(); i++) {
            frequency[clean1.charAt(i) - 'a']++;
            frequency[clean2.charAt(i) - 'a']--;
        }

        for (int count : frequency) {
            if (count != 0) return false;
        }

        return true;
    }
}

public class RunLengthCompressor {
    public static String compress(String input) {
        if (input == null || input.isEmpty()) return "";

        StringBuilder compressed = new StringBuilder();
        int count = 1;

        for (int i = 0; i < input.length(); i++) {
            if (i + 1 < input.length() && input.charAt(i) == input.charAt(i + 1)) {
                count++;
            } else {
                compressed.append(input.charAt(i)).append(count);
                count = 1;
            }
        }
        return compressed.toString();
    }
}

public class CaesarCipher {
    public static String transform(String text, int shift) {
        if (text == null) return "";

        char[] chars = text.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (Character.isUpperCase(c)) {
                chars[i] = (char) ('A' + (c - 'A' + shift % 26 + 26) % 26);
            } else if (Character.isLowerCase(c)) {
                chars[i] = (char) ('a' + (c - 'a' + shift % 26 + 26) % 26);
            }
        }
        return new String(chars);
    }
}

public class PasswordStrengthEvaluator {
    public static void evaluatePassword(String password) {
        if (password == null || password.length() < 8) {
            System.out.println("WEAK: Minimum 8 characters required.");
            return;
        }

        boolean hasUpper = false, hasLower = false, hasDigit = false, hasSpecial = false;
        String specials = "!@#$%^&*()-_=+[]{}|;:,.<>?";

        for (char ch : password.toCharArray()) {
            if (Character.isUpperCase(ch)) hasUpper = true;
            else if (Character.isLowerCase(ch)) hasLower = true;
            else if (Character.isDigit(ch)) hasDigit = true;
            else if (specials.indexOf(ch) != -1) hasSpecial = true;
        }

        int score = (hasUpper ? 25 : 0) + (hasLower ? 25 : 0) +
                    (hasDigit ? 25 : 0) + (hasSpecial ? 25 : 0);

        System.out.println("Password Score: " + score + "/100");
        System.out.println("Status: " + (score == 100 ? "EXCELLENT" : score >= 75 ? "GOOD" : "NEEDS IMPROVEMENT"));
    }
}

public class DocumentStatisticsEngine {
    public static void generateStats(String document) {
        if (document == null || document.isBlank()) {
            System.out.println("Empty or whitespace document provided.");
            return;
        }

        String trimmed = document.trim();
        String[] words = trimmed.split("\\s+");
        String[] sentences = trimmed.split("[.!?]+");

        int totalCharCount = 0;
        for (String w : words) totalCharCount += w.length();

        double avgLength = words.length > 0 ? (double) totalCharCount / words.length : 0;

        System.out.println("Total Words     : " + words.length);
        System.out.println("Total Sentences : " + sentences.length);
        System.out.println("Avg Word Length : " + String.format("%.2f", avgLength));
    }
}

import java.util.HashMap;
import java.util.Map;

public class StringPoolSimulator {
    private final Map<String, String> pool = new HashMap<>();

    public String getPooled(String input) {
        if (input == null) return null;

        // If string value already in pool, return pooled reference
        if (pool.containsKey(input)) {
            return pool.get(input);
        }

        // Otherwise store and return canonical reference
        pool.put(input, input);
        return input;
    }

    public int getUniqueObjectCount() {
        return pool.size();
    }
}

public class SemanticVersionComparator {
    public static int compareVersions(String v1, String v2) {
        String[] parts1 = v1.split("\\.");
        String[] parts2 = v2.split("\\.");

        int maxLength = Math.max(parts1.length, parts2.length);

        for (int i = 0; i < maxLength; i++) {
            int num1 = (i < parts1.length) ? Integer.parseInt(parts1[i]) : 0;
            int num2 = (i < parts2.length) ? Integer.parseInt(parts2[i]) : 0;

            if (num1 != num2) {
                return (num1 > num2) ? 1 : -1;
            }
        }
        return 0; // Both versions are numerically equivalent
    }
}

public class FileExtensionResolver {
    public static String getMimeType(String filePath) {
        if (filePath == null) return "application/octet-stream";

        int lastSlash = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));
        String fileName = (lastSlash != -1) ? filePath.substring(lastSlash + 1) : filePath;

        int dotIndex = fileName.lastIndexOf('.');

        // Guard against hidden files without extension (e.g. '.gitignore') or no extension
        if (dotIndex <= 0 || dotIndex == fileName.length() - 1) {
            return "text/plain";
        }

        String ext = fileName.substring(dotIndex + 1).toLowerCase();

        switch (ext) {
            case "java": return "text/x-java-source";
            case "json": return "application/json";
            case "html": return "text/html";
            case "pdf":  return "application/pdf";
            case "png":  return "image/png";
            default:     return "application/octet-stream";
        }
    }
}
